import{_ as t,o as n,c as l,a2 as o,j as e,a}from"./chunks/framework.CdvW4CUT.js";const b=JSON.parse('{"title":"Kernel 日报 2026-11-10","description":"","frontmatter":{},"headers":[],"relativePath":"notes/kernel-digest/2026/11/10.md","filePath":"notes/kernel-digest/2026/11/10.md"}'),i={name:"notes/kernel-digest/2026/11/10.md"};function c(s,r,m,p,d,h){return n(),l("div",null,[...r[0]||(r[0]=[o('<h1 id="kernel-日报-2026-11-10" tabindex="-1">Kernel 日报 2026-11-10 <a class="header-anchor" href="#kernel-日报-2026-11-10" aria-label="Permalink to &quot;Kernel 日报 2026-11-10&quot;">​</a></h1><blockquote><p>生成时间：2026-11-10T01:33:05Z｜共 30 条</p></blockquote><blockquote><p>深读：使用条目前 12 位 id，运行 <code>python -m kernel_digest deep --date 2026-11-10 --id &lt;id&gt;</code>。</p></blockquote><h2 id="今日-top-5" tabindex="-1">今日 Top 5 <a class="header-anchor" href="#今日-top-5" aria-label="Permalink to &quot;今日 Top 5&quot;">​</a></h2><h3 id="_590b87b109a8-·-patch-0-2-mm-avoid-redundant-reads-of-the-vm-refcnt-cacheline-in-anonymous-faults" tabindex="-1"><code>590b87b109a8</code> · <a href="https://lore.kernel.org/all/20261110000002.1834454-1-san55@wisc.edu/" target="_blank" rel="noreferrer">[PATCH 0/2] mm: avoid redundant reads of the vm_refcnt cacheline in anonymous faults</a> <a class="header-anchor" href="#_590b87b109a8-·-patch-0-2-mm-avoid-redundant-reads-of-the-vm-refcnt-cacheline-in-anonymous-faults" aria-label="Permalink to &quot;`590b87b109a8` · [[PATCH 0/2] mm: avoid redundant reads of the vm_refcnt cacheline in anonymous faults](https://lore.kernel.org/all/20261110000002.1834454-1-san55@wisc.edu/)&quot;">​</a></h3><p><em>Seunghyun An (<a href="mailto:san55@wisc.edu" target="_blank" rel="noreferrer">san55@wisc.edu</a>)｜linux-mm｜内存管理</em></p><p>该系列补丁旨在消除匿名缺页路径上对 vm_refcnt cacheline 的冗余读取。在 per-VMA-lock 缺页路径中，vma_start_read()/vma_end_read() 已使该缓存行在 CPU 间迁移，而 __folio_set_anon() 读取 __vm_anon_pgoff_hi 以及 __vmf_anon_prepare() -&gt; vma_has_anon_rmap() 中的 vma_is_attached() 和 vma_assert_stabilised() 又额外加载了同一缓存行。</p><blockquote><p><strong>学习价值</strong>：系统性地剖析了缺页热路径上的缓存行争用来源，对理解 per-VMA lock 与性能优化方法论很有帮助。</p></blockquote><h3 id="_39fdc7c0337b-·-patch-v1-mm-rmap-fix-migration-entries-being-treated-as-partial-unmaps" tabindex="-1"><code>39fdc7c0337b</code> · <a href="https://lore.kernel.org/all/20261109220958.2071687-1-joannelkoong@gmail.com/" target="_blank" rel="noreferrer">[PATCH v1] mm/rmap: fix migration entries being treated as partial unmaps</a> <a class="header-anchor" href="#_39fdc7c0337b-·-patch-v1-mm-rmap-fix-migration-entries-being-treated-as-partial-unmaps" aria-label="Permalink to &quot;`39fdc7c0337b` · [[PATCH v1] mm/rmap: fix migration entries being treated as partial unmaps](https://lore.kernel.org/all/20261109220958.2071687-1-joannelkoong@gmail.com/)&quot;">​</a></h3><p><em>Joanne Koong (<a href="mailto:joannelkoong@gmail.com" target="_blank" rel="noreferrer">joannelkoong@gmail.com</a>)｜linux-mm｜内存管理</em></p><p>该补丁修复 try_to_migrate_one() 在迁移大匿名 folio 时，migration entries 被误判为部分解除映射的问题。逐个替换 PTE 为 migration entry 的过程中，__folio_remove_rmap() 看到不再完全映射的 folio 便调用 deferred_split_folio()，错误地将其标记为 PG_partially_mapped 并放入延迟分裂队列，而实际上没有任何页面真正解除映射。</p><blockquote><p><strong>学习价值</strong>：深入展示了 migration entries 与 rmap 计数的交互细节，是理解大 folio 迁移与延迟分裂机制的好材料。</p></blockquote><h3 id="_9e39e531b6bf-·-chacha-avx-512-optimization-for-linux-7-5-yields-up-to-99-improvement-on-amd-zen-5" tabindex="-1"><code>9e39e531b6bf</code> · <a href="https://www.phoronix.com/news/ChaCha-AVX-512-Linux-7.5" target="_blank" rel="noreferrer">ChaCha AVX-512 Optimization For Linux 7.5 Yields Up To 99% Improvement On AMD Zen 5</a> <a class="header-anchor" href="#_9e39e531b6bf-·-chacha-avx-512-optimization-for-linux-7-5-yields-up-to-99-improvement-on-amd-zen-5" aria-label="Permalink to &quot;`9e39e531b6bf` · [ChaCha AVX-512 Optimization For Linux 7.5 Yields Up To 99% Improvement On AMD Zen 5](https://www.phoronix.com/news/ChaCha-AVX-512-Linux-7.5)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix｜其他动态</em></p><p>Linux 内核的 ChaCha 对称流密码代码此前已有 AVX-512 优化路径，但主要针对早期因降频问题而受限的 Intel Skylake 处理器。Linux 7.5 中将针对当前不受降频限制的 Intel 和 AMD 处理器调优，在 AMD Zen 5 上 ChaCha 性能最高提升 99%。</p><blockquote><p><strong>学习价值</strong>：是学习内核 crypto 子系统中 SIMD 指令优化（AVX-512）与 CPU 微架构特性如何影响性能的绝佳案例。</p></blockquote><h3 id="_33c05c67fe77-·-rfc-patch-0-2-percpu-local-lock-drop-btf-type-tag-where-no-compiler-records-it" tabindex="-1"><code>33c05c67fe77</code> · <a href="https://lore.kernel.org/all/20261110012235.1024461-1-vineet.gupta@linux.dev/" target="_blank" rel="noreferrer">[RFC PATCH 0/2] percpu, local_lock: drop btf_type_tag where no compiler records it</a> <a class="header-anchor" href="#_33c05c67fe77-·-rfc-patch-0-2-percpu-local-lock-drop-btf-type-tag-where-no-compiler-records-it" aria-label="Permalink to &quot;`33c05c67fe77` · [[RFC PATCH 0/2] percpu, local_lock: drop btf_type_tag where no compiler records it](https://lore.kernel.org/all/20261110012235.1024461-1-vineet.gupta@linux.dev/)&quot;">​</a></h3><p><em>Vineet Gupta (vineet.gupta@linux.dev)｜lkml｜其他动态</em></p><p>本系列目标是在 GCC 下启用 PAHOLE_HAS_BTF_TAG（目前仅限 Clang）。尽管 GCC 相关修复（PR128479、PR125991）在推进，x86 defconfig 仍产生约 4 万条 -Wattributes 警告，足以破坏 -Werror 构建；GCC 侧修复请求（PR128480）被拒绝，因此内核选择在无意义的位置移除 btf_type_tag。</p><blockquote><p><strong>学习价值</strong>：展示了内核与编译器社区协作解决构建问题的真实过程，对理解 BTF、pahole 与工具链依赖很有价值。</p></blockquote><h3 id="_0ca9ff10b6e3-·-linux-7-5-to-convey-to-user-space-multi-grain-timestamp-usage-on-files" tabindex="-1"><code>0ca9ff10b6e3</code> · <a href="https://www.phoronix.com/news/Linux-7.5-Statx-MG-TImestamp" target="_blank" rel="noreferrer">Linux 7.5 To Convey To User-Space Multi-Grain Timestamp Usage On Files</a> <a class="header-anchor" href="#_0ca9ff10b6e3-·-linux-7-5-to-convey-to-user-space-multi-grain-timestamp-usage-on-files" aria-label="Permalink to &quot;`0ca9ff10b6e3` · [Linux 7.5 To Convey To User-Space Multi-Grain Timestamp Usage On Files](https://www.phoronix.com/news/Linux-7.5-Statx-MG-TImestamp)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix｜其他动态</em></p><p>Linux 6.13 合入的 multigrain timestamp 支持允许按文件在粗粒度与细粒度时间戳之间切换，最初用于解决 NFS 缓存问题。其局限是用户空间无法得知某文件的时间戳是否为 multi-grain，Linux 7.5 将向用户空间暴露这一信息。</p><blockquote><p><strong>学习价值</strong>：有助于理解 VFS 时间戳精度与 NFS 缓存一致性之间的权衡，是 inode/timestamp 机制的很好案例。</p></blockquote><h2 id="分类目录" tabindex="-1">分类目录 <a class="header-anchor" href="#分类目录" aria-label="Permalink to &quot;分类目录&quot;">​</a></h2><ul><li><strong>内存管理</strong>（8 条）</li><li><strong>网络</strong>（5 条）</li><li><strong>版本发布动态</strong>（1 条）</li><li><strong>其他动态</strong>（16 条）</li></ul><h2 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h2><h3 id="_9349f81d81ae-·-patch-2-2-docs-admin-guide-mm-damon-reclaim-improve-language" tabindex="-1"><code>9349f81d81ae</code> · <a href="https://lore.kernel.org/all/20261110010558.104905-3-sj@kernel.org/" target="_blank" rel="noreferrer">[PATCH 2/2] Docs/admin-guide/mm/damon/reclaim: improve language</a> <a class="header-anchor" href="#_9349f81d81ae-·-patch-2-2-docs-admin-guide-mm-damon-reclaim-improve-language" aria-label="Permalink to &quot;`9349f81d81ae` · [[PATCH 2/2] Docs/admin-guide/mm/damon/reclaim: improve language](https://lore.kernel.org/all/20261110010558.104905-3-sj@kernel.org/)&quot;">​</a></h3><p><em>SJ Park (<a href="mailto:sj@kernel.org" target="_blank" rel="noreferrer">sj@kernel.org</a>)｜linux-mm</em></p><p>对 DAMON_RECLAIM 的管理员文档（Docs/admin-guide/mm/damon/reclaim）进行语言润色：修正大小写与时态、将 &#39;set as&#39; 改为 &#39;set to&#39;、重写复杂句子以提升可读性。由 Manuel Ebner 撰写，SJ Park 审核并批量转发。</p><blockquote><p><strong>学习价值</strong>：提醒学习者内核文档质量同样重要，也是了解 DAMON_RECLAIM 用法文档的入口。</p></blockquote>',31),e("h3",{id:"e68d4bc581e4-·-patch-1-2-mm-damon-core-use-list-next-prev-entry-in-damon-region",tabindex:"-1"},[e("code",null,"e68d4bc581e4"),a(" · "),e("a",{href:"https://lore.kernel.org/all/20261110010558.104905-2-sj@kernel.org/",target:"_blank",rel:"noreferrer"},[a("[PATCH 1/2] mm/damon/core: use list_{next,prev}"),e("em",{"next,prev":""},"entry() in damon"),a("_region()")]),a(),e("a",{class:"header-anchor",href:"#e68d4bc581e4-·-patch-1-2-mm-damon-core-use-list-next-prev-entry-in-damon-region","aria-label":'Permalink to "`e68d4bc581e4` · [[PATCH 1/2] mm/damon/core: use list_{next,prev}_entry() in damon_{next,prev}_region()](https://lore.kernel.org/all/20261110010558.104905-2-sj@kernel.org/)"'},"​")],-1),o('<p><em>SJ Park (<a href="mailto:sj@kernel.org" target="_blank" rel="noreferrer">sj@kernel.org</a>)｜linux-mm</em></p><p>damon_next_region() 和 damon_prev_region() 原先手动用 container_of() 从链表取相邻 region，补丁改为使用 list.h 的 list_next_entry() 和 list_prev_entry() 辅助函数，与 damon_first_region()/damon_last_region() 保持一致。</p><blockquote><p><strong>学习价值</strong>：典型的小型代码清理，示范了如何用标准链表辅助函数替代手写 container_of() 提升可维护性。</p></blockquote><h3 id="_93717280338f-·-patch-0-2-mm-damon-cleanup-region-iterator-and-damon-reclaim-user-doc" tabindex="-1"><code>93717280338f</code> · <a href="https://lore.kernel.org/all/20261110010558.104905-1-sj@kernel.org/" target="_blank" rel="noreferrer">[PATCH 0/2] mm/damon: cleanup region iterator and damon_reclaim user doc</a> <a class="header-anchor" href="#_93717280338f-·-patch-0-2-mm-damon-cleanup-region-iterator-and-damon-reclaim-user-doc" aria-label="Permalink to &quot;`93717280338f` · [[PATCH 0/2] mm/damon: cleanup region iterator and damon_reclaim user doc](https://lore.kernel.org/all/20261110010558.104905-1-sj@kernel.org/)&quot;">​</a></h3><p><em>SJ Park (<a href="mailto:sj@kernel.org" target="_blank" rel="noreferrer">sj@kernel.org</a>)｜linux-mm</em></p><p>DAMON 子系统的两个简单清理补丁的批量转发：一是用专用链表访问器重写 damon_{next,prev}_region()（Enze Li），二是改进 DAMON_RECLAIM 用户文档的拼写与语法（Manuel Ebner）。这是 SJ Park 为 mm.git 合并请求目的的重发。</p><blockquote><p><strong>学习价值</strong>：展示了维护者如何批量收集并转发贡献者补丁，可了解 DAMON 子系统的维护工作流。</p></blockquote><h3 id="f618cda0bea3-·-patch-mm-hotfixes-unstable-v3-mm-damon-stat-avoid-overflow-in-estimated-memory-bandwidth-calculation" tabindex="-1"><code>f618cda0bea3</code> · <a href="https://lore.kernel.org/all/20261110004816.100066-1-sj@kernel.org/" target="_blank" rel="noreferrer">[PATCH mm-hotfixes-unstable v3] mm/damon/stat: avoid overflow in estimated_memory_bandwidth calculation</a> <a class="header-anchor" href="#f618cda0bea3-·-patch-mm-hotfixes-unstable-v3-mm-damon-stat-avoid-overflow-in-estimated-memory-bandwidth-calculation" aria-label="Permalink to &quot;`f618cda0bea3` · [[PATCH mm-hotfixes-unstable v3] mm/damon/stat: avoid overflow in estimated_memory_bandwidth calculation](https://lore.kernel.org/all/20261110004816.100066-1-sj@kernel.org/)&quot;">​</a></h3><p><em>SJ Park (<a href="mailto:sj@kernel.org" target="_blank" rel="noreferrer">sj@kernel.org</a>)｜linux-mm</em></p><p>estimated_memory_bandwidth 按 access_bytes * USEC_PER_SEC / aggr_interval 计算，在 32 位系统上当 access_bytes 超过约 4294 字节时 unsigned long 溢出，导致 /sys/module/damon_stat/parameters/ 下读到错误值。修复方式是以 64 位计算并将除法拆分为商与余数，已在 qemu-system-i386 上复现验证。</p><blockquote><p><strong>学习价值</strong>：经典的 32 位算术溢出修复案例，同时演示了内核修复补丁的复现与验证方法。</p></blockquote><h3 id="_2fca6d06b12c-·-patch-1-2-mm-rmap-use-vm-pgoff-for-anonymous-vmas-in-linear-anon-page-index" tabindex="-1"><code>2fca6d06b12c</code> · <a href="https://lore.kernel.org/all/20261110000002.1834454-2-san55@wisc.edu/" target="_blank" rel="noreferrer">[PATCH 1/2] mm/rmap: use vm_pgoff for anonymous VMAs in linear_anon_page_index()</a> <a class="header-anchor" href="#_2fca6d06b12c-·-patch-1-2-mm-rmap-use-vm-pgoff-for-anonymous-vmas-in-linear-anon-page-index" aria-label="Permalink to &quot;`2fca6d06b12c` · [[PATCH 1/2] mm/rmap: use vm_pgoff for anonymous VMAs in linear_anon_page_index()](https://lore.kernel.org/all/20261110000002.1834454-2-san55@wisc.edu/)&quot;">​</a></h3><p><em>Seunghyun An (<a href="mailto:san55@wisc.edu" target="_blank" rel="noreferrer">san55@wisc.edu</a>)｜linux-mm</em></p><p>该补丁修改 linear_anon_page_index()，使其对匿名 VMA 使用 vm_pgoff。自 commit 93c0c8dc87f6 引入 anon pgoff 机制后，__folio_set_anon() 在每次匿名缺页时都会读取 __vm_anon_pgoff_hi，而该字段紧邻 vm_refcnt 所在的 cacheline，多线程在同一 VMA 上缺页时会造成缓存行乒乓，引发额外的缓存一致性传输开销。</p><blockquote><p><strong>学习价值</strong>：展示了 cacheline 布局对并发路径性能的微妙影响，是学习伪共享（false sharing）与 rmap 机制的绝佳案例。</p></blockquote><h3 id="_590b87b109a8-·-patch-0-2-mm-avoid-redundant-reads-of-the-vm-refcnt-cacheline-in-anonymous-faults-1" tabindex="-1"><code>590b87b109a8</code> · <a href="https://lore.kernel.org/all/20261110000002.1834454-1-san55@wisc.edu/" target="_blank" rel="noreferrer">[PATCH 0/2] mm: avoid redundant reads of the vm_refcnt cacheline in anonymous faults</a> <a class="header-anchor" href="#_590b87b109a8-·-patch-0-2-mm-avoid-redundant-reads-of-the-vm-refcnt-cacheline-in-anonymous-faults-1" aria-label="Permalink to &quot;`590b87b109a8` · [[PATCH 0/2] mm: avoid redundant reads of the vm_refcnt cacheline in anonymous faults](https://lore.kernel.org/all/20261110000002.1834454-1-san55@wisc.edu/)&quot;">​</a></h3><p><em>Seunghyun An (<a href="mailto:san55@wisc.edu" target="_blank" rel="noreferrer">san55@wisc.edu</a>)｜linux-mm</em></p><p>该系列补丁旨在消除匿名缺页路径上对 vm_refcnt cacheline 的冗余读取。在 per-VMA-lock 缺页路径中，vma_start_read()/vma_end_read() 已使该缓存行在 CPU 间迁移，而 __folio_set_anon() 读取 __vm_anon_pgoff_hi 以及 __vmf_anon_prepare() -&gt; vma_has_anon_rmap() 中的 vma_is_attached() 和 vma_assert_stabilised() 又额外加载了同一缓存行。</p><blockquote><p><strong>学习价值</strong>：系统性地剖析了缺页热路径上的缓存行争用来源，对理解 per-VMA lock 与性能优化方法论很有帮助。</p></blockquote><h3 id="fa74f7b54695-·-patch-2-2-mm-vma-only-assert-vma-stability-in-vma-has-anon-rmap-with-config-debug-vm" tabindex="-1"><code>fa74f7b54695</code> · <a href="https://lore.kernel.org/all/20261110000002.1834454-3-san55@wisc.edu/" target="_blank" rel="noreferrer">[PATCH 2/2] mm/vma: only assert VMA stability in vma_has_anon_rmap() with CONFIG_DEBUG_VM</a> <a class="header-anchor" href="#fa74f7b54695-·-patch-2-2-mm-vma-only-assert-vma-stability-in-vma-has-anon-rmap-with-config-debug-vm" aria-label="Permalink to &quot;`fa74f7b54695` · [[PATCH 2/2] mm/vma: only assert VMA stability in vma_has_anon_rmap() with CONFIG_DEBUG_VM](https://lore.kernel.org/all/20261110000002.1834454-3-san55@wisc.edu/)&quot;">​</a></h3><p><em>Seunghyun An (<a href="mailto:san55@wisc.edu" target="_blank" rel="noreferrer">san55@wisc.edu</a>)｜linux-mm</em></p><p>该补丁将 vma_has_anon_rmap() 中的 vma_assert_stabilised() 断言限制在 CONFIG_DEBUG_VM 开启时执行。即使 VM_WARN_ON_ONCE_VMA() 检查在编译时被消除，refcount_read() 和 rwsem_is_locked() 的原子读取（READ_ONCE）仍会保留在非 DEBUG 构建中，导致每次匿名缺页额外加载 vm_refcnt 两次。</p><blockquote><p><strong>学习价值</strong>：提醒学习者：即使断言条件被编译掉，其操作数读取也可能因原子语义而保留，是理解编译器优化边界的实例。</p></blockquote><h3 id="_39fdc7c0337b-·-patch-v1-mm-rmap-fix-migration-entries-being-treated-as-partial-unmaps-1" tabindex="-1"><code>39fdc7c0337b</code> · <a href="https://lore.kernel.org/all/20261109220958.2071687-1-joannelkoong@gmail.com/" target="_blank" rel="noreferrer">[PATCH v1] mm/rmap: fix migration entries being treated as partial unmaps</a> <a class="header-anchor" href="#_39fdc7c0337b-·-patch-v1-mm-rmap-fix-migration-entries-being-treated-as-partial-unmaps-1" aria-label="Permalink to &quot;`39fdc7c0337b` · [[PATCH v1] mm/rmap: fix migration entries being treated as partial unmaps](https://lore.kernel.org/all/20261109220958.2071687-1-joannelkoong@gmail.com/)&quot;">​</a></h3><p><em>Joanne Koong (<a href="mailto:joannelkoong@gmail.com" target="_blank" rel="noreferrer">joannelkoong@gmail.com</a>)｜linux-mm</em></p><p>该补丁修复 try_to_migrate_one() 在迁移大匿名 folio 时，migration entries 被误判为部分解除映射的问题。逐个替换 PTE 为 migration entry 的过程中，__folio_remove_rmap() 看到不再完全映射的 folio 便调用 deferred_split_folio()，错误地将其标记为 PG_partially_mapped 并放入延迟分裂队列，而实际上没有任何页面真正解除映射。</p><blockquote><p><strong>学习价值</strong>：深入展示了 migration entries 与 rmap 计数的交互细节，是理解大 folio 迁移与延迟分裂机制的好材料。</p></blockquote><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><h3 id="_7f5ed2b7159e-·-patch-myri10ge-correct-uninitialized-variable-use" tabindex="-1"><code>7f5ed2b7159e</code> · <a href="https://lore.kernel.org/all/20261109235730.2519016-1-mark.j.nicholson@oracle.com/" target="_blank" rel="noreferrer">[PATCH] myri10ge: correct uninitialized variable use</a> <a class="header-anchor" href="#_7f5ed2b7159e-·-patch-myri10ge-correct-uninitialized-variable-use" aria-label="Permalink to &quot;`7f5ed2b7159e` · [[PATCH] myri10ge: correct uninitialized variable use](https://lore.kernel.org/all/20261109235730.2519016-1-mark.j.nicholson@oracle.com/)&quot;">​</a></h3><p><em>Mark Nicholson (<a href="mailto:mark.j.nicholson@oracle.com" target="_blank" rel="noreferrer">mark.j.nicholson@oracle.com</a>)｜netdev</em></p><p>该补丁修复 myri10ge 驱动中 myri10ge_dummy_rdma() 使用未初始化变量的问题。使用 GCC 16.2.1 为 aarch64 编译时，__iowrite64_copy 内联到 __const_memcpy_to_io_aligned64 后，buf[6] 处的 u64 读取被 -Werror=uninitialized 报错。</p><blockquote><p><strong>学习价值</strong>：一个典型的编译器新版本暴露驱动未初始化内存问题的案例，展示了内核如何通过构建系统保证代码质量。</p></blockquote><h3 id="_7e7eef995d4e-·-patch-net-next-v8-14-15-ibmveth-implement-incremental-mq-rx-queue-resize" tabindex="-1"><code>7e7eef995d4e</code> · <a href="https://lore.kernel.org/all/20261109235556.60604-15-mmc@linux.ibm.com/" target="_blank" rel="noreferrer">[PATCH net-next v8 14/15] ibmveth: Implement incremental MQ RX queue resize</a> <a class="header-anchor" href="#_7e7eef995d4e-·-patch-net-next-v8-14-15-ibmveth-implement-incremental-mq-rx-queue-resize" aria-label="Permalink to &quot;`7e7eef995d4e` · [[PATCH net-next v8 14/15] ibmveth: Implement incremental MQ RX queue resize](https://lore.kernel.org/all/20261109235556.60604-15-mmc@linux.ibm.com/)&quot;">​</a></h3><p><em>Mingming Cao (<a href="mailto:mmc@linux.ibm.com" target="_blank" rel="noreferrer">mmc@linux.ibm.com</a>)｜netdev</em></p><p>该补丁为 ibmveth 实现增量式 MQ RX 队列调整，使 ethtool -L 可在设备运行时逐个队列地改变 RX 队列数量而无需完整 close/open。扩容时逐个分配队列、向 PHYP 注册、设置 IRQ 并启用 NAPI；缩容时静默排空队列后逐个注销释放；任一方向的失败都会回退到一致的存活队列数。</p><blockquote><p><strong>学习价值</strong>：展示了网络设备热路径下队列动态调整的完整工程实现，对学习驱动状态机与错误回滚设计很有参考价值。</p></blockquote><h3 id="_4a0bba381886-·-patch-net-next-v8-15-15-ibmveth-complete-set-channels-down-path" tabindex="-1"><code>4a0bba381886</code> · <a href="https://lore.kernel.org/all/20261109235556.60604-16-mmc@linux.ibm.com/" target="_blank" rel="noreferrer">[PATCH net-next v8 15/15] ibmveth: Complete set_channels down-path</a> <a class="header-anchor" href="#_4a0bba381886-·-patch-net-next-v8-15-15-ibmveth-complete-set-channels-down-path" aria-label="Permalink to &quot;`4a0bba381886` · [[PATCH net-next v8 15/15] ibmveth: Complete set_channels down-path](https://lore.kernel.org/all/20261109235556.60604-16-mmc@linux.ibm.com/)&quot;">​</a></h3><p><em>Mingming Cao (<a href="mailto:mmc@linux.ibm.com" target="_blank" rel="noreferrer">mmc@linux.ibm.com</a>)｜netdev</em></p><p>该补丁补全 ibmveth 的 set_channels 下行路径，替换前一补丁中临时的 -EOPNOTSUPP。设备关闭时可发布期望的 RX/TX 队列数而不涉及 PHYP 注册、buffer pool 或 IRQ 设置；设备运行时先校验 tx_count 再调整 RX，并在 tx_count 不变时跳过 TX LTB 工作。</p><blockquote><p><strong>学习价值</strong>：展示了 ethtool channel 配置接口在驱动中的完整实现细节，适合学习 netdev 子系统的配置路径。</p></blockquote><h3 id="_21a23ce5c2f4-·-patch-net-next-v8-11-15-ibmveth-add-per-queue-rx-and-tx-statistics-collection" tabindex="-1"><code>21a23ce5c2f4</code> · <a href="https://lore.kernel.org/all/20261109235556.60604-12-mmc@linux.ibm.com/" target="_blank" rel="noreferrer">[PATCH net-next v8 11/15] ibmveth: Add per-queue RX and TX statistics collection</a> <a class="header-anchor" href="#_21a23ce5c2f4-·-patch-net-next-v8-11-15-ibmveth-add-per-queue-rx-and-tx-statistics-collection" aria-label="Permalink to &quot;`21a23ce5c2f4` · [[PATCH net-next v8 11/15] ibmveth: Add per-queue RX and TX statistics collection](https://lore.kernel.org/all/20261109235556.60604-12-mmc@linux.ibm.com/)&quot;">​</a></h3><p><em>Mingming Cao (<a href="mailto:mmc@linux.ibm.com" target="_blank" rel="noreferrer">mmc@linux.ibm.com</a>)｜netdev</em></p><p>该补丁为 ibmveth 添加每队列的 RX/TX 统计。多队列 RX 指向同一适配器级计数器会导致更新竞争且无法归因到具体队列，因此将多写者计数器移入每队列结构体，每个槽位只有一个写者；通过 netdev_stat_ops 报告每队列的包数、字节数和硬件丢包，ndo_get_stats64() 汇总所有槽位。</p><blockquote><p><strong>学习价值</strong>：演示了如何正确设计每队列统计以避免多核竞争，是学习 per-CPU/per-queue 计数模式的实用范例。</p></blockquote><h3 id="_2092fa472dfc-·-patch-net-next-v8-13-15-ibmveth-expose-per-queue-buffer-pool-details-via-debugfs" tabindex="-1"><code>2092fa472dfc</code> · <a href="https://lore.kernel.org/all/20261109235556.60604-14-mmc@linux.ibm.com/" target="_blank" rel="noreferrer">[PATCH net-next v8 13/15] ibmveth: Expose per-queue buffer pool details via debugfs</a> <a class="header-anchor" href="#_2092fa472dfc-·-patch-net-next-v8-13-15-ibmveth-expose-per-queue-buffer-pool-details-via-debugfs" aria-label="Permalink to &quot;`2092fa472dfc` · [[PATCH net-next v8 13/15] ibmveth: Expose per-queue buffer pool details via debugfs](https://lore.kernel.org/all/20261109235556.60604-14-mmc@linux.ibm.com/)&quot;">​</a></h3><p><em>Mingming Cao (<a href="mailto:mmc@linux.ibm.com" target="_blank" rel="noreferrer">mmc@linux.ibm.com</a>)｜netdev</em></p><p>该补丁通过 debugfs 暴露 ibmveth 每队列的 buffer pool 详情。多队列 RX 下每个队列拥有五个 buffer pool（16 队列即 80 个），但 sysfs 只暴露队列 0 的配置，ethtool 也没有每 pool 的键；新增只读的 buffer_pools debugfs 文件，每行显示一个 RX 队列和 buffer pool 的计数、大小、活跃与可用状态。</p><blockquote><p><strong>学习价值</strong>：展示了如何用 debugfs 为驱动添加运行时可观测性，是学习内核调试接口设计的简洁示例。</p></blockquote><h2 id="版本发布动态" tabindex="-1">版本发布动态 <a class="header-anchor" href="#版本发布动态" aria-label="Permalink to &quot;版本发布动态&quot;">​</a></h2><h3 id="_4088679a573d-·-next-20261109-linux-next" tabindex="-1"><code>4088679a573d</code> · <a href="https://www.kernel.org/#kernel.org-linux-next-next-20261109-2026-11-09" target="_blank" rel="noreferrer">next-20261109: linux-next</a> <a class="header-anchor" href="#_4088679a573d-·-next-20261109-linux-next" aria-label="Permalink to &quot;`4088679a573d` · [next-20261109: linux-next](https://www.kernel.org/#kernel.org-linux-next-next-20261109-2026-11-09)&quot;">​</a></h3><p><em>kernel.org</em></p><p>linux-next 于 2026 年 11 月 9 日发布 next-20261109 版本。linux-next 是集成各子系统树待合并补丁的测试树，供开发者在进入主线前验证构建与启动。</p><blockquote><p><strong>学习价值</strong>：跟踪 linux-next 版本有助于学习者了解即将进入主线的最新改动，是观察内核开发流程的窗口。</p></blockquote><h2 id="其他动态" tabindex="-1">其他动态 <a class="header-anchor" href="#其他动态" aria-label="Permalink to &quot;其他动态&quot;">​</a></h2><h3 id="cbdcaaedfb98-·-git-considers-voting-to-determine-its-llm-policy" tabindex="-1"><code>cbdcaaedfb98</code> · <a href="https://lwn.net/Articles/1104195/" target="_blank" rel="noreferrer">[$] Git considers voting to determine its LLM policy</a> <a class="header-anchor" href="#cbdcaaedfb98-·-git-considers-voting-to-determine-its-llm-policy" aria-label="Permalink to &quot;`cbdcaaedfb98` · [[$] Git considers voting to determine its LLM policy](https://lwn.net/Articles/1104195/)&quot;">​</a></h3><p><em>corbet｜lwn｜<strong>LWN 订阅文章，仅预览</strong></em></p><p>Git 项目正在讨论是否通过投票机制来决定其 LLM 贡献政策。这一议题在 Git Contributor&#39;s Summit 上被提出，反映了 2026 年各开源项目普遍面临的 LLM 生成代码接受标准的争论。Git 项目历史上并非民主治理模式，此次考虑引入投票流程以求达成共识。</p><blockquote><p><strong>学习价值</strong>：展示了开源社区治理与 LLM 政策争论的真实案例，有助于理解内核等大型开源项目在 AI 时代面临的贡献规范挑战。</p></blockquote><h3 id="_8712779a5205-·-kernel-prepatch-7-4-rc2" tabindex="-1"><code>8712779a5205</code> · <a href="https://lwn.net/Articles/1106300/" target="_blank" rel="noreferrer">Kernel prepatch 7.4-rc2</a> <a class="header-anchor" href="#_8712779a5205-·-kernel-prepatch-7-4-rc2" aria-label="Permalink to &quot;`8712779a5205` · [Kernel prepatch 7.4-rc2](https://lwn.net/Articles/1106300/)&quot;">​</a></h3><p><em>jake｜lwn</em></p><p>Linus Torvalds 发布了 7.4-rc2 prepatch，与史上最大的 -rc1 相对应，这个 -rc2 也很大。其中相当一部分体积来自散布全树的自动化 Coccinelle 更新；剔除这些噪音后，diffstat 分布正常：约三分之一是 drivers（以 gpu、networking 和 sound 为主），另外三分之一是网络相关改动。</p><blockquote><p><strong>学习价值</strong>：通过阅读 rc 发布说明可以学习如何解读 diffstat、理解内核发布节奏以及自动化工具（如 Coccinelle）对内核树的影响。</p></blockquote><h3 id="bf582f728959-·-openindiana-2026-10-released" tabindex="-1"><code>bf582f728959</code> · <a href="https://lwn.net/Articles/1106285/" target="_blank" rel="noreferrer">OpenIndiana 2026.10 released</a> <a class="header-anchor" href="#bf582f728959-·-openindiana-2026-10-released" aria-label="Permalink to &quot;`bf582f728959` · [OpenIndiana 2026.10 released](https://lwn.net/Articles/1106285/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>OpenIndiana 2026.10 发布。OpenIndiana 基于 Illumos（源自 Oracle 停止维护后的 OpenSolaris），本次更新包括 live image 的 UEFI framebuffer 支持、大量应用和开发工具升级，并新增 TeX Live 2026、Foliate 电子书阅读器等应用。</p><blockquote><p><strong>学习价值</strong>：与 Linux 内核无直接关系，但可作为了解 Illumos/Solaris 系 Unix 生态演进的背景资料。</p></blockquote><h3 id="_9849d24f76d2-·-security-updates-for-monday" tabindex="-1"><code>9849d24f76d2</code> · <a href="https://lwn.net/Articles/1106282/" target="_blank" rel="noreferrer">Security updates for Monday</a> <a class="header-anchor" href="#_9849d24f76d2-·-security-updates-for-monday" aria-label="Permalink to &quot;`9849d24f76d2` · [Security updates for Monday](https://lwn.net/Articles/1106282/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>Debian、Fedora 等发行版发布了例行安全更新，涉及 kernel、rsync、zlib、vim、多个 Java 相关组件等大量软件包。这类公告是发行版安全响应流程的常规组成部分。</p><blockquote><p><strong>学习价值</strong>：提醒学习者关注发行版层面的 kernel 安全补丁，是跟踪内核 CVE 修复动向的日常渠道。</p></blockquote><h3 id="_310ef49a191d-·-mesa-26-3-released-with-vk-amd-anti-lag-for-radv-many-other-vulkan-improvements" tabindex="-1"><code>310ef49a191d</code> · <a href="https://www.phoronix.com/news/Mesa-26.3-Released" target="_blank" rel="noreferrer">Mesa 26.3 Released With VK_AMD_anti_lag For RADV, Many Other Vulkan Improvements</a> <a class="header-anchor" href="#_310ef49a191d-·-mesa-26-3-released-with-vk-amd-anti-lag-for-radv-many-other-vulkan-improvements" aria-label="Permalink to &quot;`310ef49a191d` · [Mesa 26.3 Released With VK_AMD_anti_lag For RADV, Many Other Vulkan Improvements](https://www.phoronix.com/news/Mesa-26.3-Released)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Mesa 26.3 作为第四季度的 Mesa3D 功能版本发布，包含面向 RADV 的 VK_AMD_anti_lag 扩展支持以及大量其他 Vulkan 改进。Mesa 是开源 OpenGL/Vulkan 驱动的集合。</p><blockquote><p><strong>学习价值</strong>：Mesa 与内核 DRM 子系统紧密协作，了解其版本节奏有助于理解 Linux 图形栈的整体演进。</p></blockquote><h3 id="_57d3f558c525-·-firefox-160-available-with-speech-to-text-mkv-files-with-flac-mp3-pcm-audio" tabindex="-1"><code>57d3f558c525</code> · <a href="https://www.phoronix.com/news/Firefox-160-Released" target="_blank" rel="noreferrer">Firefox 160 Available With Speech-To-Text, MKV Files With FLAC / MP3 / PCM Audio</a> <a class="header-anchor" href="#_57d3f558c525-·-firefox-160-available-with-speech-to-text-mkv-files-with-flac-mp3-pcm-audio" aria-label="Permalink to &quot;`57d3f558c525` · [Firefox 160 Available With Speech-To-Text, MKV Files With FLAC / MP3 / PCM Audio](https://www.phoronix.com/news/Firefox-160-Released)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Firefox 160.0 稳定版发布，新增语音转文字（Speech-To-Text）功能，并支持包含 FLAC/MP3/PCM 音轨的 MKV 文件播放。</p><blockquote><p><strong>学习价值</strong>：属于用户态浏览器更新，与内核学习关联很小。</p></blockquote><h3 id="d45078d5a8f6-·-amdgpu-linux-driver-patches-posted-for-enabling-gfx13-graphics-ip-rdna5" tabindex="-1"><code>d45078d5a8f6</code> · <a href="https://www.phoronix.com/news/AMDGPU-Patches-GFX13" target="_blank" rel="noreferrer">AMDGPU Linux Driver Patches Posted For Enabling GFX13 Graphics IP - RDNA5</a> <a class="header-anchor" href="#d45078d5a8f6-·-amdgpu-linux-driver-patches-posted-for-enabling-gfx13-graphics-ip-rdna5" aria-label="Permalink to &quot;`d45078d5a8f6` · [AMDGPU Linux Driver Patches Posted For Enabling GFX13 Graphics IP - RDNA5](https://www.phoronix.com/news/AMDGPU-Patches-GFX13)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>AMD 发布了针对 GFX13 图形 IP 的 AMDGPU Linux 内核驱动补丁，GFX13 很可能对应下一代 RDNA 5 架构。此前年初已有 GFX13 的 LLVM 后端补丁，此次是内核驱动侧的首次公开亮相。</p><blockquote><p><strong>学习价值</strong>：展示了新硬件 IP 如何从编译器后端到内核 DRM 驱动逐步进入 Linux 图形栈的完整流程，对学习 AMDGPU 驱动开发节奏很有参考价值。</p></blockquote><h3 id="a67326a89478-·-darling-now-embraces-ai-for-running-macos-binaries-on-linux" tabindex="-1"><code>a67326a89478</code> · <a href="https://www.phoronix.com/news/Darling-Using-AI-macOS-Linux" target="_blank" rel="noreferrer">Darling Now Embraces AI For Running macOS Binaries On Linux</a> <a class="header-anchor" href="#a67326a89478-·-darling-now-embraces-ai-for-running-macos-binaries-on-linux" aria-label="Permalink to &quot;`a67326a89478` · [Darling Now Embraces AI For Running macOS Binaries On Linux](https://www.phoronix.com/news/Darling-Using-AI-macOS-Linux)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Darling 是一个开发超过十年、旨在 Linux 上运行 macOS 二进制文件的兼容层项目，如今开始借助 AI/LLM 辅助开发以加快进度。</p><blockquote><p><strong>学习价值</strong>：与内核学习关联不大，但体现了 AI 辅助系统级软件开发的趋势。</p></blockquote><h3 id="_9e39e531b6bf-·-chacha-avx-512-optimization-for-linux-7-5-yields-up-to-99-improvement-on-amd-zen-5-1" tabindex="-1"><code>9e39e531b6bf</code> · <a href="https://www.phoronix.com/news/ChaCha-AVX-512-Linux-7.5" target="_blank" rel="noreferrer">ChaCha AVX-512 Optimization For Linux 7.5 Yields Up To 99% Improvement On AMD Zen 5</a> <a class="header-anchor" href="#_9e39e531b6bf-·-chacha-avx-512-optimization-for-linux-7-5-yields-up-to-99-improvement-on-amd-zen-5-1" aria-label="Permalink to &quot;`9e39e531b6bf` · [ChaCha AVX-512 Optimization For Linux 7.5 Yields Up To 99% Improvement On AMD Zen 5](https://www.phoronix.com/news/ChaCha-AVX-512-Linux-7.5)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Linux 内核的 ChaCha 对称流密码代码此前已有 AVX-512 优化路径，但主要针对早期因降频问题而受限的 Intel Skylake 处理器。Linux 7.5 中将针对当前不受降频限制的 Intel 和 AMD 处理器调优，在 AMD Zen 5 上 ChaCha 性能最高提升 99%。</p><blockquote><p><strong>学习价值</strong>：是学习内核 crypto 子系统中 SIMD 指令优化（AVX-512）与 CPU 微架构特性如何影响性能的绝佳案例。</p></blockquote><h3 id="_97d0d8b635eb-·-linux-seeing-driver-work-for-msi-mystic-light-on-latest-ryzen-motherboards" tabindex="-1"><code>97d0d8b635eb</code> · <a href="https://www.phoronix.com/news/MSI-Mystic-Light-Linux" target="_blank" rel="noreferrer">Linux Seeing Driver Work For MSI Mystic Light On Latest Ryzen Motherboards</a> <a class="header-anchor" href="#_97d0d8b635eb-·-linux-seeing-driver-work-for-msi-mystic-light-on-latest-ryzen-motherboards" aria-label="Permalink to &quot;`97d0d8b635eb` · [Linux Seeing Driver Work For MSI Mystic Light On Latest Ryzen Motherboards](https://www.phoronix.com/news/MSI-Mystic-Light-Linux)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>MSI 最新的 AMD 800 系列芯片组 Ryzen 主板引入了 Mystic Light RGB 灯光控制功能，官方软件仅支持 Windows。一位开源开发者在 Claude Code 的辅助下正在为 Linux 内核开发 Mystic Light 开源驱动。</p><blockquote><p><strong>学习价值</strong>：展示了社区开发者如何借助 AI 工具逆向并实现 Linux 硬件驱动（hid/platform 驱动），是了解小众外设驱动开发流程的有趣案例。</p></blockquote><h3 id="_0ca9ff10b6e3-·-linux-7-5-to-convey-to-user-space-multi-grain-timestamp-usage-on-files-1" tabindex="-1"><code>0ca9ff10b6e3</code> · <a href="https://www.phoronix.com/news/Linux-7.5-Statx-MG-TImestamp" target="_blank" rel="noreferrer">Linux 7.5 To Convey To User-Space Multi-Grain Timestamp Usage On Files</a> <a class="header-anchor" href="#_0ca9ff10b6e3-·-linux-7-5-to-convey-to-user-space-multi-grain-timestamp-usage-on-files-1" aria-label="Permalink to &quot;`0ca9ff10b6e3` · [Linux 7.5 To Convey To User-Space Multi-Grain Timestamp Usage On Files](https://www.phoronix.com/news/Linux-7.5-Statx-MG-TImestamp)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Linux 6.13 合入的 multigrain timestamp 支持允许按文件在粗粒度与细粒度时间戳之间切换，最初用于解决 NFS 缓存问题。其局限是用户空间无法得知某文件的时间戳是否为 multi-grain，Linux 7.5 将向用户空间暴露这一信息。</p><blockquote><p><strong>学习价值</strong>：有助于理解 VFS 时间戳精度与 NFS 缓存一致性之间的权衡，是 inode/timestamp 机制的很好案例。</p></blockquote><h3 id="_4768b7030af5-·-new-linux-patches-bring-up-the-samsung-galaxy-xr-headset-qualcomm-halliday-soc" tabindex="-1"><code>4768b7030af5</code> · <a href="https://www.phoronix.com/news/Linux-Samsung-Galaxy-XR" target="_blank" rel="noreferrer">New Linux Patches Bring-Up The Samsung Galaxy XR Headset, Qualcomm Halliday SoC</a> <a class="header-anchor" href="#_4768b7030af5-·-new-linux-patches-bring-up-the-samsung-galaxy-xr-headset-qualcomm-halliday-soc" aria-label="Permalink to &quot;`4768b7030af5` · [New Linux Patches Bring-Up The Samsung Galaxy XR Headset, Qualcomm Halliday SoC](https://www.phoronix.com/news/Linux-Samsung-Galaxy-XR)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>一位用户借助多个 LLM 起草了初始补丁集，让 Samsung Galaxy XR 头显及其搭载的 Qualcomm Snapdragon XR2+ Gen 2 &quot;Halliday&quot; SoC 能在主线内核上启动运行。该设备默认运行 Android XR 并使用下游内核补丁。</p><blockquote><p><strong>学习价值</strong>：展示了新硬件 mainline bring-up 的典型流程，对了解设备树与 SoC 支持的合入路径有参考价值。</p></blockquote><h3 id="_55ab80fa920a-·-intel-anv-lands-bitrate-control-for-av1-encoding" tabindex="-1"><code>55ab80fa920a</code> · <a href="https://www.phoronix.com/news/Intel-ANV-AV1-Bitrate-Control" target="_blank" rel="noreferrer">Intel ANV Lands Bitrate Control For AV1 Encoding</a> <a class="header-anchor" href="#_55ab80fa920a-·-intel-anv-lands-bitrate-control-for-av1-encoding" aria-label="Permalink to &quot;`55ab80fa920a` · [Intel ANV Lands Bitrate Control For AV1 Encoding](https://www.phoronix.com/news/Intel-ANV-AV1-Bitrate-Control)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Igalia 的 Hyunjun Ko 持续完善 Mesa ANV 驱动（Intel Vulkan）的 Vulkan Video 支持，本次为 AV1 编码加入了 bitrate control 能力，以改进开源视频加速。</p><blockquote><p><strong>学习价值</strong>：属于用户态图形/视频驱动进展，与内核学习关联较弱，仅作生态动态了解。</p></blockquote><h3 id="_121d81c64c5e-·-rfc-patch-2-2-local-lock-do-not-put-btf-type-tag-on-the-lock-guard-type" tabindex="-1"><code>121d81c64c5e</code> · <a href="https://lore.kernel.org/all/20261110012235.1024461-3-vineet.gupta@linux.dev/" target="_blank" rel="noreferrer">[RFC PATCH 2/2] local_lock: do not put btf_type_tag on the lock guard type</a> <a class="header-anchor" href="#_121d81c64c5e-·-rfc-patch-2-2-local-lock-do-not-put-btf-type-tag-on-the-lock-guard-type" aria-label="Permalink to &quot;`121d81c64c5e` · [[RFC PATCH 2/2] local_lock: do not put btf_type_tag on the lock guard type](https://lore.kernel.org/all/20261110012235.1024461-3-vineet.gupta@linux.dev/)&quot;">​</a></h3><p><em>Vineet Gupta (vineet.gupta@linux.dev)｜lkml</em></p><p>该补丁修改 local_lock.h，使 DEFINE_LOCK_GUARD_1(local_lock, local_lock_t __percpu, ...) 不再把 __percpu（即 BTF_TYPE_TAG）加到 lock guard 类型上，从而消除 GCC 在定义后忽略属性的 -Wattributes 警告，避免 -Werror 构建失败。同一模式也适用于 local_lock_irq、local_lock_irqsave 和 local_lock_nested_bh。</p><blockquote><p><strong>学习价值</strong>：结合 cleanup.h 的 guard 机制与 BTF type tag，是理解内核锁抽象与编译器属性交互的好材料。</p></blockquote><h3 id="_577b98847c71-·-rfc-patch-1-2-percpu-do-not-put-btf-type-tag-on-per-cpu-variable-declarations" tabindex="-1"><code>577b98847c71</code> · <a href="https://lore.kernel.org/all/20261110012235.1024461-2-vineet.gupta@linux.dev/" target="_blank" rel="noreferrer">[RFC PATCH 1/2] percpu: do not put btf_type_tag on per-cpu variable declarations</a> <a class="header-anchor" href="#_577b98847c71-·-rfc-patch-1-2-percpu-do-not-put-btf-type-tag-on-per-cpu-variable-declarations" aria-label="Permalink to &quot;`577b98847c71` · [[RFC PATCH 1/2] percpu: do not put btf_type_tag on per-cpu variable declarations](https://lore.kernel.org/all/20261110012235.1024461-2-vineet.gupta@linux.dev/)&quot;">​</a></h3><p><em>Vineet Gupta (vineet.gupta@linux.dev)｜lkml</em></p><p>__percpu 携带 BTF_TYPE_TAG(percpu) 用于标记指向 per-cpu 内存的指针，但 __PCPU_ATTRS() 会把它加在变量自身类型上，导致 GCC 报 &quot;ignoring attributes applied after definition&quot; 警告。补丁调整 DECLARE_PER_CPU/DEFINE_PER_CPU，使 btf_type_tag 不再出现在编译器不记录的位置。</p><blockquote><p><strong>学习价值</strong>：深入剖析 percpu 声明宏与 BTF type tag 的实现细节，适合学习内核宏体系与编译器属性语义。</p></blockquote><h3 id="_33c05c67fe77-·-rfc-patch-0-2-percpu-local-lock-drop-btf-type-tag-where-no-compiler-records-it-1" tabindex="-1"><code>33c05c67fe77</code> · <a href="https://lore.kernel.org/all/20261110012235.1024461-1-vineet.gupta@linux.dev/" target="_blank" rel="noreferrer">[RFC PATCH 0/2] percpu, local_lock: drop btf_type_tag where no compiler records it</a> <a class="header-anchor" href="#_33c05c67fe77-·-rfc-patch-0-2-percpu-local-lock-drop-btf-type-tag-where-no-compiler-records-it-1" aria-label="Permalink to &quot;`33c05c67fe77` · [[RFC PATCH 0/2] percpu, local_lock: drop btf_type_tag where no compiler records it](https://lore.kernel.org/all/20261110012235.1024461-1-vineet.gupta@linux.dev/)&quot;">​</a></h3><p><em>Vineet Gupta (vineet.gupta@linux.dev)｜lkml</em></p><p>本系列目标是在 GCC 下启用 PAHOLE_HAS_BTF_TAG（目前仅限 Clang）。尽管 GCC 相关修复（PR128479、PR125991）在推进，x86 defconfig 仍产生约 4 万条 -Wattributes 警告，足以破坏 -Werror 构建；GCC 侧修复请求（PR128480）被拒绝，因此内核选择在无意义的位置移除 btf_type_tag。</p><blockquote><p><strong>学习价值</strong>：展示了内核与编译器社区协作解决构建问题的真实过程，对理解 BTF、pahole 与工具链依赖很有价值。</p></blockquote><h2 id="深读候选" tabindex="-1">深读候选 <a class="header-anchor" href="#深读候选" aria-label="Permalink to &quot;深读候选&quot;">​</a></h2><p>以下条目适合优先深读（按条目前的 id 手动生成）：</p><ul><li><code>590b87b109a8</code> · <a href="https://lore.kernel.org/all/20261110000002.1834454-1-san55@wisc.edu/" target="_blank" rel="noreferrer">[PATCH 0/2] mm: avoid redundant reads of the vm_refcnt cacheline in anonymous faults</a></li><li><code>39fdc7c0337b</code> · <a href="https://lore.kernel.org/all/20261109220958.2071687-1-joannelkoong@gmail.com/" target="_blank" rel="noreferrer">[PATCH v1] mm/rmap: fix migration entries being treated as partial unmaps</a></li></ul>',121)])])}const f=t(i,[["render",c]]);export{b as __pageData,f as default};
